CREATE DATABASE IF NOT EXISTS offlineai;
USE offlineai;

create table IF NOT EXISTS conversation_history( conversation_id          bigint auto_increment primary key, input_mode               varchar(20) null, created_at               datetime    null, raw_text                 longtext    null, processed_text           json        null, conversationmemory_input longtext    null, ai_response              longtext    null, run_start_time           double      null, run_end_time             double      null, run_duration             double      null, status                   varchar(50) null, error_message            text        null ) AUTO_INCREMENT = 1001;

create table IF NOT EXISTS performance_monitor ( id              int auto_increment primary key, created_at      datetime     not null, component       varchar(200) not null, start_time      double       not null, end_time        double       not null, duration        double       not null, status          varchar(100) not null, error_message   text         null, conversation_id bigint       null, constraint fk_performance_monitor_conversation foreign key (conversation_id) references conversation_history (conversation_id) );
